const row = $input.item.json[0] || $input.item.json;
const brief = row.brief_content;

// Compute scheduled publish times (LATAM friendly: IG/TT 8am MX, LinkedIn 7am MX, Newsletter 9am MX)
const now = new Date();
const tomorrow = new Date(now);
tomorrow.setDate(tomorrow.getDate() + 1);

const publishAt_IG = new Date(tomorrow); publishAt_IG.setUTCHours(14, 0, 0, 0);   // 8am CDMX UTC-6
const publishAt_TT = new Date(tomorrow); publishAt_TT.setUTCHours(14, 0, 0, 0);   // mismo
const publishAt_LI = new Date(tomorrow); publishAt_LI.setUTCHours(13, 0, 0, 0);   // 7am CDMX
const publishAt_NL = new Date(tomorrow); publishAt_NL.setUTCHours(15, 0, 0, 0);   // 9am CDMX

return {
  brief_id: row.id,
  brief,
  source_url: row.source_url,
  source_name: row.source_name,
  productos_mencionados: row.productos_mencionados || [],
  disclaimer_texto: row.disclaimer_texto || '',
  schedule: {
    instagram: publishAt_IG.toISOString(),
    tiktok: publishAt_TT.toISOString(),
    linkedin: publishAt_LI.toISOString(),
    newsletter: publishAt_NL.toISOString()
  }
};

