const items = $input.all();
const blotato = items[0]?.json || {};
const beehiiv = items[1]?.json || {};
const data = $('Extract brief content').item.json;

return {
  brief_id: data.brief_id,
  brief: data.brief,
  schedule: data.schedule,
  source_url: data.source_url,
  disclaimer_texto: data.disclaimer_texto,
  productos_mencionados: data.productos_mencionados,
  blotato: {
    carousel_id: blotato.carousel_id || null,
    slide_urls: blotato.slide_urls || [],
    pdf_url: blotato.carousel_pdf_url || null,
    status: blotato.status || 'failed',
    error: blotato.error || null
  },
  beehiiv: {
    post_id: beehiiv.data?.id || beehiiv.id || null,
    status: beehiiv.data?.status || beehiiv.status || 'failed',
    schedule_at: beehiiv.data?.scheduled_at || beehiiv.scheduled_at || null,
    error: beehiiv.error || null
  }
};

